-- Notion-style share links for user agents and recipes
-- (`/agentura/agent/<name>-<suffix>`, `/agentura/rezept/<titel>-<suffix>`),
-- following the groups/notebooks convention. `identifier` and `mention` are
-- unique only per owner, so neither can carry a link: a teammate with the same
-- mention would open instead. The suffix is the stable lookup key (survives a
-- rename), the name prefix is cosmetic. Legacy uuid links keep resolving.
--
-- The suffix is generated by the database (column DEFAULT), so every insert
-- path gets one without touching application code, and ADD COLUMN fills the
-- existing rows in the same statement (a volatile default is evaluated per
-- row). Randomness comes from gen_random_uuid() (cryptographic, core since
-- PG 13) — an unlisted "Mit Anmeldung" item is reachable by its link only, so
-- the suffix must not be predictable. Same alphabet as
-- `generateSlugSuffix` in packages/shared/src/utils/slug.ts.
--
-- The unique index is NOT partial on deleted_at: a trashed row keeps its
-- suffix, and restoring it must not collide with a newer row.

CREATE OR REPLACE FUNCTION gen_slug_suffix() RETURNS TEXT AS $$
  SELECT string_agg(
           substr('abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789',
                  1 + (get_byte(uuid_send(gen_random_uuid()), 0) % 56), 1),
           '')
    FROM generate_series(1, 6)
$$ LANGUAGE sql VOLATILE;

ALTER TABLE user_agents ADD COLUMN IF NOT EXISTS slug_suffix TEXT NOT NULL DEFAULT gen_slug_suffix();
CREATE UNIQUE INDEX IF NOT EXISTS uq_user_agents_slug_suffix ON user_agents (slug_suffix);

ALTER TABLE user_text_forms ADD COLUMN IF NOT EXISTS slug_suffix TEXT NOT NULL DEFAULT gen_slug_suffix();
CREATE UNIQUE INDEX IF NOT EXISTS uq_user_text_forms_slug_suffix ON user_text_forms (slug_suffix);
